def preencher_snapshots(apps, schema_editor):
    PedidoItem = apps.get_model('pedidos', 'PedidoItem')
    Produto = apps.get_model('produtos', 'Produto')
    db_alias = schema_editor.connection.alias
    produtos = {
        produto.pk: produto
        for produto in Produto.objects.using(db_alias).all()
    }
    itens = list(
        PedidoItem.objects.using(db_alias).select_related('produto')
    )
    for item in itens:
        produto = produtos[item.produto_id]
        item.nome_produto = produto.nome
        item.unidade_medida = produto.unidade_medida
